package com.futurelab.littled;
import android.app.Instrumentation;import android.content.Intent;import android.os.SystemClock;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.ext.junit.runners.AndroidJUnit4;import org.junit.Test;import org.junit.runner.RunWith;import static org.junit.Assert.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicReference;import org.json.JSONObject;
@RunWith(AndroidJUnit4.class) public class LaunchTest {
 @Test public void localRobotAndPrivateConfig()throws Exception{Instrumentation inst=InstrumentationRegistry.getInstrumentation();MainActivity a=(MainActivity)inst.startActivitySync(new Intent(inst.getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));String value="";for(int i=0;i<80;i++){CountDownLatch latch=new CountDownLatch(1);AtomicReference<String> found=new AtomicReference<>("");inst.runOnMainSync(()->a.web.evaluateJavascript("JSON.stringify({ready:!!window.robotStudio?.robot,hands:!!window.robotStudio?.handVisuals,scope:document.querySelector('#fatal')?.textContent,layoutFits:[document.querySelector('.viewport'),document.querySelector('.right')].every(e=>{if(!e)return false;const r=e.getBoundingClientRect();return r.top>=-1&&r.left>=-1&&r.right<=innerWidth+1&&r.bottom<=innerHeight+1}),secure:window.isSecureContext,worklet:typeof AudioWorkletNode,webgl2:!!document.createElement('canvas').getContext('webgl2')})",s->{found.set(s);latch.countDown();}));latch.await(3,TimeUnit.SECONDS);value=found.get();if(value.contains("\\\"ready\\\":true"))break;SystemClock.sleep(500);}assertTrue("Robot did not load: "+value,value.contains("\\\"ready\\\":true"));assertTrue(value.contains("\\\"hands\\\":true"));assertTrue(value.contains("\\\"secure\\\":true"));assertTrue(value.contains("\\\"webgl2\\\":true"));assertTrue(value.contains("AudioWorkletNode")||value.contains("function"));
 assertTrue("Both panels must fit inside screen: "+value,value.contains("\\\"layoutFits\\\":true")); byte[] json=MainActivity.read(inst.getContext().getAssets().open("private-config.json"),65536);a.config=new JSONObject(new String(json,"UTF-8"));a.saveConfig();assertTrue(a.configured());a.config=new JSONObject();a.loadConfig();assertTrue("Encrypted config must survive reload",a.configured());CountDownLatch answered=new CountDownLatch(1);StringBuilder reply=new StringBuilder();AtomicReference<String> error=new AtomicReference<>("");java.util.concurrent.atomic.AtomicBoolean asked=new java.util.concurrent.atomic.AtomicBoolean();String voice=new JSONObject(new String(MainActivity.read(a.getAssets().open("web/assets/robot-config.json"),65536),"UTF-8")).getString("voice");okhttp3.WebSocket socket=a.client.newWebSocket(new okhttp3.Request.Builder().url(a.origin.replace("http://","ws://")+"/realtime").header("Origin",a.origin).build(),new okhttp3.WebSocketListener(){@Override public void onMessage(okhttp3.WebSocket ws,String message){try{JSONObject e=new JSONObject(message);String type=e.optString("type");if(!type.contains("delta"))System.out.println("AI_TEST_EVENT "+type);if(type.equals("session.created")){JSONObject output=new JSONObject().put("voice",voice).put("format",new JSONObject().put("type","pcm").put("sample_rate",24000));JSONObject session=new JSONObject().put("modalities",new org.json.JSONArray().put("text").put("audio")).put("instructions","你是小D。请用一句中文自我介绍。").put("audio",new JSONObject().put("output",output)).put("turn_detection",JSONObject.NULL);ws.send(new JSONObject().put("type","session.update").put("session",session).toString());}if(type.equals("session.updated")&&asked.compareAndSet(false,true)){JSONObject content=new JSONObject().put("type","input_text").put("text","你好，请用一句话自我介绍。");ws.send(new JSONObject().put("type","conversation.item.create").put("item",new JSONObject().put("type","message").put("role","user").put("content",new org.json.JSONArray().put(content))).toString());ws.send("{\"type\":\"response.create\"}");}if(type.endsWith("transcript.delta")||type.equals("response.text.delta"))reply.append(e.optString("delta"));if(type.equals("response.done"))answered.countDown();if(type.equals("error")||type.equals("relay.error")){error.set(e.toString());answered.countDown();}}catch(Exception ex){error.set(ex.toString());answered.countDown();}}@Override public void onFailure(okhttp3.WebSocket ws,Throwable t,okhttp3.Response response){error.set(t.toString());answered.countDown();}});assertTrue("Native AI timed out",answered.await(50,TimeUnit.SECONDS));socket.close(1000,"test complete");assertEquals("Native AI relay failed: "+error.get(),"",error.get());assertTrue("AI produced no transcript",reply.length()>0);System.out.println("PASS_NATIVE_AI "+reply);
 try(android.os.ParcelFileDescriptor permission=inst.getUiAutomation().executeShellCommand("pm grant com.futurelab.littled android.permission.RECORD_AUDIO")){new java.io.FileInputStream(permission.getFileDescriptor()).readAllBytes();}
 inst.runOnMainSync(()->a.web.evaluateJavascript("window.__nativePcm=0;window.addEventListener('littled-native-audio',e=>{if(e.detail.type==='pcm'&&atob(e.detail.audio).length===3200)window.__nativePcm++});document.querySelector('#testNativeMic').click()",null));
 String audioResult="";for(int i=0;i<50;i++){CountDownLatch audioLatch=new CountDownLatch(1);AtomicReference<String> measured=new AtomicReference<>("");inst.runOnMainSync(()->a.web.evaluateJavascript("JSON.stringify({pcm:window.__nativePcm>=2,playing:window.robotStudio.audioState==='running',diagnostic:document.querySelector('#nativeMicStatus').textContent})",v->{measured.set(v);audioLatch.countDown();}));audioLatch.await(2,TimeUnit.SECONDS);audioResult=measured.get();if(audioResult.contains("\\\"pcm\\\":true"))break;SystemClock.sleep(200);}assertTrue("Native microphone must supply PCM frames: "+audioResult,audioResult.contains("\\\"pcm\\\":true"));assertTrue("Playback must remain running: "+audioResult,audioResult.contains("\\\"playing\\\":true"));
 inst.runOnMainSync(()->a.web.evaluateJavascript("document.querySelector('#testNativeMic').click()",null));SystemClock.sleep(400);assertNull("Recorder must release after stopping",a.nativeAudio.recorder);System.out.println("PASS_NATIVE_MIC_AND_PLAYBACK "+audioResult);
 inst.runOnMainSync(()->a.web.evaluateJavascript("document.querySelector('#ptt').click();document.querySelector('#ptt').dispatchEvent(new PointerEvent('pointerup'))",null));
 String talkResult="";for(int i=0;i<80;i++){CountDownLatch talkLatch=new CountDownLatch(1);AtomicReference<String> observed=new AtomicReference<>("");inst.runOnMainSync(()->a.web.evaluateJavascript("JSON.stringify({active:document.querySelector('#autoMic').checked,label:document.querySelector('#ptt').textContent,status:document.querySelector('#aiStatus').textContent})",v->{observed.set(v);talkLatch.countDown();}));talkLatch.await(2,TimeUnit.SECONDS);talkResult=observed.get();if(talkResult.contains("\\\"active\\\":true"))break;SystemClock.sleep(250);}assertTrue("One click must start automatic conversation and stay active after release: "+talkResult,talkResult.contains("\\\"active\\\":true"));
 inst.runOnMainSync(()->a.web.evaluateJavascript("document.querySelector('#ptt').click()",null));SystemClock.sleep(500);assertNull("Second click must release microphone",a.nativeAudio.recorder);System.out.println("PASS_CLICK_CONVERSATION "+talkResult);

System.out.println("PASS_ANDROID13 "+value);}
 @Test public void pcmResampling(){for(int rate:new int[]{16000,48000,44100})for(int channels:new int[]{1,2}){NativeAudio.PcmConverter converter=new NativeAudio.PcmConverter(rate,channels);short[] samples=new short[rate*channels];java.util.Arrays.fill(samples,(short)1234);java.util.ArrayList<byte[]> frames=new java.util.ArrayList<>();converter.append(samples,samples.length,frames::add);assertEquals(10,frames.size());for(byte[] frame:frames){assertEquals(3200,frame.length);for(int i=0;i<frame.length;i+=2)assertEquals(1234,(short)((frame[i]&255)|((frame[i+1]&255)<<8)));}}}
}
